public static double SafeRate(double rate, double lifetime, int capacity)
{
    double r = System.Math.Max(0.0, rate);
    double lt = System.Math.Max(0.05, lifetime);
    double cap = System.Math.Max(0.0, capacity);
    double maxRate = cap * 0.8 / lt;
    return System.Math.Min(r, maxRate);
}
